{"summary":"Create config.go","command":"create","path":"/workspace/backend/internal/config/config.go","file_text":"package config

import (
	"os"
)

type Config struct {
	Port          string
	DatabaseURL   string
	AdminUsername string
	AdminPassword string
	JWTSecret     string
	MapAssetsDir  string
	FrontendDir   string
}

func LoadConfig() *Config {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}

	adminUser := os.Getenv("ADMIN_USERNAME")
	if adminUser == "" {
		adminUser = "admin"
	}

	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminPass == "" {
		adminPass = "admin123"
	}

	jwtSecret := os.Getenv("JWT_SECRET")
	if jwtSecret == "" {
		jwtSecret = "lab-transport-jwt-secret-2026-secure-key"
	}

	mapAssetsDir := os.Getenv("MAP_ASSETS_DIR")
	if mapAssetsDir == "" {
		mapAssetsDir = "/opt/arena/map-assets"
	}

	frontendDir := os.Getenv("FRONTEND_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}

	return &Config{
		Port:          port,
		DatabaseURL:   dbURL,
		AdminUsername: adminUser,
		AdminPassword: adminPass,
		JWTSecret:     jwtSecret,
		MapAssetsDir:  mapAssetsDir,
		FrontendDir:   frontendDir,
	}
}
"}

{"summary":"Create db.go","file_text":"package db

import (
	"context"
	_ "embed"
	"fmt"
	"log"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

//go:embed schema.sql
var schemaSQL string

//go:embed seed.sql
var seedSQL string

type DB struct {
	Pool *pgxpool.Pool
}

func Connect(ctx context.Context, databaseURL string) (*DB, error) {
	config, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		return nil, fmt.Errorf("failed to parse db config: %w", err)
	}

	config.MaxConns = 25
	config.MinConns = 2
	config.MaxConnLifetime = 1 * time.Hour

	pool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		return nil, fmt.Errorf("failed to create pool: %w", err)
	}

	if err := pool.Ping(ctx); err != nil {
		return nil, fmt.Errorf("failed to ping db: %w", err)
	}

	return &DB{Pool: pool}, nil
}

func (db *DB) InitSchema(ctx context.Context) error {
	if _, err := db.Pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("failed to execute schema: %w", err)
	}
	if _, err := db.Pool.Exec(ctx, seedSQL); err != nil {
		return fmt.Errorf("failed to execute seed: %w", err)
	}
	return nil
}

func (db *DB) Reset(ctx context.Context) error {
	dropSQL := `
		DROP TABLE IF EXISTS
			worker_penalties,
			serviceability_snapshots,
			idempotency_keys,
			realtime_events,
			audit_entries,
			checkpoints,
			worker_locations,
			handoffs,
			assignments,
			journey_stops,
			journeys,
			samples,
			requests,
			connections,
			locations,
			sample_types,
			sessions,
			users
		CASCADE;
	`
	if _, err := db.Pool.Exec(ctx, dropSQL); err != nil {
		return fmt.Errorf("failed to drop tables: %w", err)
	}

	return db.InitSchema(ctx)
}

func (db *DB) EnsureAdmin(ctx context.Context, username, password string) error {
	var count int
	err := db.Pool.QueryRow(ctx, "SELECT COUNT(*) FROM users").Scan(&count)
	if err != nil {
		return fmt.Errorf("failed to count users: %w", err)
	}

	if count > 0 {
		return nil
	}

	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return fmt.Errorf("failed to hash password: %w", err)
	}

	adminID := uuid.New().String()
	rolesJSON := `["administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"]`
	qualificationsJSON := `["cert_amber", "cert_indigo", "cert_frost", "cert_pulse", "qualified_collector"]`
	certificationsJSON := `[
		{"code": "cert_amber", "active": true},
		{"code": "cert_indigo", "active": true},
		{"code": "cert_frost", "active": true},
		{"code": "cert_pulse", "active": true}
	]`

	insertSQL := `
		INSERT INTO users (id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, available, capacity_units)
		VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, $8::jsonb, $9::jsonb, true, true, 10)
		ON CONFLICT (username) DO NOTHING
	`
	_, err = db.Pool.Exec(ctx, insertSQL,
		adminID,
		username,
		string(hashedPassword),
		username+"@all-hands.dev",
		"System Administrator",
		"+91-9999999999",
		rolesJSON,
		qualificationsJSON,
		certificationsJSON,
	)
	if err != nil {
		return fmt.Errorf("failed to insert initial admin: %w", err)
	}

	log.Printf("Initial administrator created: %s (id: %s)", username, adminID)
	return nil
}
