{"path":"/workspace/backend/internal/routing/serviceability.go","file_text":"package routing

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	"lab-transport/internal/db"
	"lab-transport/internal/models"
)

type Node struct {
	ID                    string
	Name                  string
	Latitude              float64
	Longitude             float64
	CoverageKm            float64
	HandlingMinutes       int
	Active                bool
	Functions             models.LocationFunctionStates
	CapacityUnits         int
	ReservedUnits         int
	CooledCapacityUnits   int
	CooledReservedUnits   int
	AcceptedSampleTypeIDs []string
}

type Edge struct {
	ID                  string
	FromLocationID      string
	ToLocationID        string
	TravelMinutes       int
	CostUnits           float64
	Cooled              bool
	Active              bool
	CapacityUnits       int
	ReservedUnits       int
	CooledCapacityUnits int
	CooledReservedUnits int
}

type NetworkGraph struct {
	Nodes map[string]Node
	Edges map[string][]Edge // fromNodeID -> list of outgoing edges
}

type ServiceabilityEngine struct {
	db              *db.DB
	mu              sync.RWMutex
	currentSnapshot *ServiceabilitySnapshotData
}

type ServiceabilitySnapshotData struct {
	Version             int                          `json:"version"`
	NetworkRevision     int                          `json:"networkRevision"`
	ComputedAt          time.Time                    `json:"computedAt"`
	Status              string                       `json:"status"`
	ActiveRegions       []models.ServiceabilityRegion `json:"activeRegions"`
	ActiveLocations     []models.OperationsLocation  `json:"activeLocations"`
	ActiveConnections   []models.OperationsConnection `json:"activeConnections"`
}

type RoutePlanResult struct {
	Serviceable        bool
	Reason             string
	TargetLaboratoryID string
	CollectionNodeID   string
	Stops              []models.JourneyStop
	Legs               []models.JourneyLeg
	TotalTravelMinutes int
	TotalCostUnits     float64
	EstimatedDelivery  time.Time
}

func NewServiceabilityEngine(database *db.DB) *ServiceabilityEngine {
	engine := &ServiceabilityEngine{db: database}
	_ = engine.RecomputeSnapshot(context.Background())
	return engine
}

func HaversineDistanceKm(lat1, lon1, lat2, lon2 float64) float64 {
	const earthRadiusKm = 6371.0

	dLat := (lat2 - lat1) * (math.Pi / 180.0)
	dLon := (lon2 - lon1) * (math.Pi / 180.0)

	rLat1 := lat1 * (math.Pi / 180.0)
	rLat2 := lat2 * (math.Pi / 180.0)

	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Sin(dLon/2)*math.Sin(dLon/2)*math.Cos(rLat1)*math.Cos(rLat2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))

	return earthRadiusKm * c
}

func (e *ServiceabilityEngine) LoadGraph(ctx context.Context) (*NetworkGraph, error) {
	graph := &NetworkGraph{
		Nodes: make(map[string]Node),
		Edges: make(map[string][]Edge),
	}

	locRows, err := e.db.Pool.Query(ctx, `
		SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_type_ids
		FROM locations
	`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	for locRows.Next() {
		var n Node
		var funcBytes, sampleBytes []byte
		if err := locRows.Scan(
			&n.ID, &n.Name, &n.Latitude, &n.Longitude, &n.CoverageKm, &n.HandlingMinutes, &n.Active, &funcBytes,
			&n.CapacityUnits, &n.ReservedUnits, &n.CooledCapacityUnits, &n.CooledReservedUnits, &sampleBytes,
		); err != nil {
			return nil, err
		}
		_ = json.Unmarshal(funcBytes, &n.Functions)
		_ = json.Unmarshal(sampleBytes, &n.AcceptedSampleTypeIDs)
		graph.Nodes[n.ID] = n
	}

	connRows, err := e.db.Pool.Query(ctx, `
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	for connRows.Next() {
		var edge Edge
		if err := connRows.Scan(
			&edge.ID, &edge.FromLocationID, &edge.ToLocationID, &edge.TravelMinutes, &edge.CostUnits, &edge.Cooled, &edge.Active,
			&edge.CapacityUnits, &edge.ReservedUnits, &edge.CooledCapacityUnits, &edge.CooledReservedUnits,
		); err != nil {
			return nil, err
		}
		graph.Edges[edge.FromLocationID] = append(graph.Edges[edge.FromLocationID], edge)
	}

	return graph, nil
}

func (e *ServiceabilityEngine) RecomputeSnapshot(ctx context.Context) error {
	graph, err := e.LoadGraph(ctx)
	if err != nil {
		return err
	}

	var latestVersion int
	var networkRev int
	err = e.db.Pool.QueryRow(ctx, "SELECT COALESCE(MAX(version), 0), COALESCE(MAX(network_revision), 0) FROM serviceability_snapshots").Scan(&latestVersion, &networkRev)
	if err != nil {
		latestVersion = 0
		networkRev = 0
	}
	newVersion := latestVersion + 1
	newRev := networkRev + 1

	var activeRegions []models.ServiceabilityRegion
	var activeLocations []models.OperationsLocation
	var activeConnections []models.OperationsConnection

	for _, n := range graph.Nodes {
		if !n.Active {
			continue
		}
		if n.Functions.CollectionPoint {
			activeRegions = append(activeRegions, models.ServiceabilityRegion{
				LocationId: n.ID,
				Name:       n.Name,
				Latitude:   n.Latitude,
				Longitude:  n.Longitude,
				CoverageKm: n.CoverageKm,
			})
		}
		activeLocations = append(activeLocations, models.OperationsLocation{
			ID:              n.ID,
			LocationId:      n.ID,
			Name:            n.Name,
			Coordinate:      models.Coordinate{Latitude: n.Latitude, Longitude: n.Longitude},
			Active:          n.Active,
			CoverageKm:      n.CoverageKm,
			HandlingMinutes: n.HandlingMinutes,
			Functions:       n.Functions,
			Capacity: &models.Capacity{
				CapacityUnits:       n.CapacityUnits,
				ReservedUnits:       n.ReservedUnits,
				AvailableUnits:      n.CapacityUnits - n.ReservedUnits,
				CooledCapacityUnits: n.CooledCapacityUnits,
				CooledReservedUnits: n.CooledReservedUnits,
				CooledAvailableUnits: n.CooledCapacityUnits - n.CooledReservedUnits,
			},
			AcceptedSampleTypeIDs: n.AcceptedSampleTypeIDs,
		})
	}

	for _, edges := range graph.Edges {
		for _, edge := range edges {
			if !edge.Active {
				continue
			}
			activeConnections = append(activeConnections, models.OperationsConnection{
				ID:             edge.ID,
				ConnectionId:   edge.ID,
				FromLocationId: edge.FromLocationID,
				ToLocationId:   edge.ToLocationID,
				TravelMinutes:  edge.TravelMinutes,
				CostUnits:      edge.CostUnits,
				Cooled:         edge.Cooled,
				Active:         edge.Active,
				Capacity: &models.Capacity{
					CapacityUnits:       edge.CapacityUnits,
					ReservedUnits:       edge.ReservedUnits,
					AvailableUnits:      edge.CapacityUnits - edge.ReservedUnits,
					CooledCapacityUnits: edge.CooledCapacityUnits,
					CooledReservedUnits: edge.CooledReservedUnits,
					CooledAvailableUnits: edge.CooledCapacityUnits - edge.CooledReservedUnits,
				},
			})
		}
	}

	snapData := ServiceabilitySnapshotData{
		Version:           newVersion,
		NetworkRevision:   newRev,
		ComputedAt:        time.Now().UTC(),
		Status:            "complete",
		ActiveRegions:     activeRegions,
		ActiveLocations:   activeLocations,
		ActiveConnections: activeConnections,
	}

	dataBytes, _ := json.Marshal(snapData)
	_, _ = e.db.Pool.Exec(ctx, `
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, snapshot_data)
		VALUES ($1, $2, $3, $4, $5)
	`, newVersion, "complete", snapData.ComputedAt, newRev, dataBytes)

	e.mu.Lock()
	e.currentSnapshot = &snapData
	e.mu.Unlock()

	return nil
}

func (e *ServiceabilityEngine) GetCurrentSnapshot() *ServiceabilitySnapshotData {
	e.mu.RLock()
	defer e.mu.RUnlock()
	return e.currentSnapshot
}

func (e *ServiceabilityEngine) EvaluateServiceability(
	ctx context.Context,
	origin models.Coordinate,
	originType string,
	originNodeID string,
	sampleType models.SampleType,
	requestedAt time.Time,
	deliveryDeadline time.Time,
	earliestCollectionAt *time.Time,
	latestCollectionAt *time.Time,
) (*RoutePlanResult, error) {
	graph, err := e.LoadGraph(ctx)
	if err != nil {
		return nil, err
	}

	// 1. Find entry / collection node
	var entryNode *Node
	if originType == "node" && originNodeID != "" {
		if node, exists := graph.Nodes[originNodeID]; exists && node.Active {
			entryNode = &node
		} else {
			return &RoutePlanResult{
				Serviceable: false,
				Reason:      "origin_node_inactive_or_not_found",
			}, nil
		}
	} else {
		// Find closest active collection point within coverage
		var bestDistance float64 = 1e9
		for _, n := range graph.Nodes {
			if n.Active && n.Functions.CollectionPoint {
				dist := HaversineDistanceKm(origin.Latitude, origin.Longitude, n.Latitude, n.Longitude)
				maxCoverage := n.CoverageKm
				if maxCoverage <= 0 {
					maxCoverage = 5.0
				}
				if dist <= maxCoverage && dist < bestDistance {
					bestDistance = dist
					nodeCopy := n
					entryNode = &nodeCopy
				}
			}
		}

		if entryNode == nil {
			return &RoutePlanResult{
				Serviceable: false,
				Reason:      "out_of_coverage_area",
			}, nil
		}
	}

	// 2. Find eligible laboratories accepting sampleType
	var eligibleLabs []Node
	for _, n := range graph.Nodes {
		if n.Active && n.Functions.Laboratory {
			accepted := false
			for _, tid := range n.AcceptedSampleTypeIDs {
				if tid == sampleType.SampleTypeId {
					accepted = true
					break
				}
			}
			if accepted {
				eligibleLabs = append(eligibleLabs, n)
			}
		}
	}

	if len(eligibleLabs) == 0 {
		return &RoutePlanResult{
			Serviceable: false,
			Reason:      "no_accepting_laboratory_available",
		}, nil
	}

	// 3. Find path to best laboratory
	var bestResult *RoutePlanResult

	collectionTime := requestedAt
	if earliestCollectionAt != nil && earliestCollectionAt.After(collectionTime) {
		collectionTime = *earliestCollectionAt
	}

	for _, lab := range eligibleLabs {
		plan := e.findPath(graph, entryNode.ID, lab.ID, sampleType, collectionTime, deliveryDeadline)
		if plan != nil && plan.Serviceable {
			if bestResult == nil || plan.EstimatedDelivery.Before(bestResult.EstimatedDelivery) {
				plan.CollectionNodeID = entryNode.ID
				bestResult = plan
			}
		}
	}

	if bestResult != nil {
		return bestResult, nil
	}

	return &RoutePlanResult{
		Serviceable: false,
		Reason:      "no_valid_route_or_deadline_unmet",
	}, nil
}

type pathState struct {
	nodeID       string
	timeMinutes  int
	cost         float64
	edges        []Edge
	visitedNodes map[string]bool
}

func (e *ServiceabilityEngine) findPath(
	graph *NetworkGraph,
	startNodeID string,
	targetLabID string,
	sampleType models.SampleType,
	startTime time.Time,
	deadline time.Time,
) *RoutePlanResult {
	if startNodeID == targetLabID {
		entryNode := graph.Nodes[startNodeID]
		// Check capacity
		if sampleType.RequiresCooledRoute {
			if entryNode.CooledCapacityUnits-entryNode.CooledReservedUnits <= 0 {
				return nil
			}
		} else {
			if entryNode.CapacityUnits-entryNode.ReservedUnits <= 0 {
				return nil
			}
		}

		estDelivery := startTime.Add(time.Duration(entryNode.HandlingMinutes) * time.Minute)
		if estDelivery.After(deadline) {
			return nil
		}

		stops := []models.JourneyStop{
			{
				StopId:      startNodeID + "-stop-1",
				LocationId:  startNodeID,
				StopType:    "delivery",
				Sequence:    1,
				EstimatedAt: estDelivery,
				Coordinate:  &models.Coordinate{Latitude: entryNode.Latitude, Longitude: entryNode.Longitude},
			},
		}

		return &RoutePlanResult{
			Serviceable:        true,
			TargetLaboratoryID: targetLabID,
			Stops:              stops,
			Legs:               []models.JourneyLeg{},
			TotalTravelMinutes: entryNode.HandlingMinutes,
			TotalCostUnits:     0,
			EstimatedDelivery:  estDelivery,
		}
	}

	// BFS/Dijkstra shortest travel time search
	queue := []pathState{
		{
			nodeID:       startNodeID,
			timeMinutes:  graph.Nodes[startNodeID].HandlingMinutes,
			cost:         0,
			edges:        []Edge{},
			visitedNodes: map[string]bool{startNodeID: true},
		},
	}

	var bestState *pathState

	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]

		if curr.nodeID == targetLabID {
			if bestState == nil || curr.timeMinutes < bestState.timeMinutes {
				currCopy := curr
				bestState = &currCopy
			}
			continue
		}

		outgoing := graph.Edges[curr.nodeID]
		for _, edge := range outgoing {
			if !edge.Active {
				continue
			}
			if curr.visitedNodes[edge.ToLocationID] {
				continue
			}
			toNode, exists := graph.Nodes[edge.ToLocationID]
			if !exists || !toNode.Active {
				continue
			}

			// Check edge capacity and cooled requirements
			if sampleType.RequiresCooledRoute {
				if !edge.Cooled || (edge.CooledCapacityUnits-edge.CooledReservedUnits <= 0) {
					continue
				}
				if toNode.CooledCapacityUnits-toNode.CooledReservedUnits <= 0 {
					continue
				}
			} else {
				if edge.CapacityUnits-edge.ReservedUnits <= 0 {
					continue
				}
				if toNode.CapacityUnits-toNode.ReservedUnits <= 0 {
					continue
				}
			}

			newVisited := make(map[string]bool)
			for k, v := range curr.visitedNodes {
				newVisited[k] = v
			}
			newVisited[edge.ToLocationID] = true

			newEdges := append([]Edge{}, curr.edges...)
			newEdges = append(newEdges, edge)

			nextState := pathState{
				nodeID:       edge.ToLocationID,
				timeMinutes:  curr.timeMinutes + edge.TravelMinutes + toNode.HandlingMinutes,
				cost:         curr.cost + edge.CostUnits,
				edges:        newEdges,
				visitedNodes: newVisited,
			}

			queue = append(queue, nextState)
		}
	}

	if bestState == nil {
		return nil
	}

	estDelivery := startTime.Add(time.Duration(bestState.timeMinutes) * time.Minute)
	if estDelivery.After(deadline) {
		return nil
	}

	// Build ordered stops and legs
	var stops []models.JourneyStop
	var legs []models.JourneyLeg

	currTime := startTime
	seq := 1

	startNode := graph.Nodes[startNodeID]
	stops = append(stops, models.JourneyStop{
		StopId:      fmt.Sprintf("%s-stop-%d", startNodeID, seq),
		LocationId:  startNodeID,
		StopType:    "pickup",
		Sequence:    seq,
		EstimatedAt: currTime,
		Coordinate:  &models.Coordinate{Latitude: startNode.Latitude, Longitude: startNode.Longitude},
	})

	for i, edge := range bestState.edges {
		toNode := graph.Nodes[edge.ToLocationID]
		currTime = currTime.Add(time.Duration(edge.TravelMinutes) * time.Minute)
		seq++

		stopType := "handoff"
		if i == len(bestState.edges)-1 {
			stopType = "delivery"
		}

		stops = append(stops, models.JourneyStop{
			StopId:      fmt.Sprintf("%s-stop-%d", edge.ToLocationID, seq),
			LocationId:  edge.ToLocationID,
			StopType:    stopType,
			Sequence:    seq,
			EstimatedAt: currTime,
			DwellMinutes: toNode.HandlingMinutes,
			Coordinate:  &models.Coordinate{Latitude: toNode.Latitude, Longitude: toNode.Longitude},
		})

		legs = append(legs, models.JourneyLeg{
			Sequence:       i + 1,
			Status:         "pending",
			FromLocationId: edge.FromLocationID,
			ToLocationId:   edge.ToLocationID,
		})

		currTime = currTime.Add(time.Duration(toNode.HandlingMinutes) * time.Minute)
	}

	return &RoutePlanResult{
		Serviceable:        true,
		TargetLaboratoryID: targetLabID,
		Stops:              stops,
		Legs:               legs,
		TotalTravelMinutes: bestState.timeMinutes,
		TotalCostUnits:     bestState.cost,
		EstimatedDelivery:  estDelivery,
	}
}
