func (s *UserService) GetUser(ctx context.Context, userID string) (*models.User, error) {
	var user models.User
	var rolesJSON, qualJSON, certJSON []byte
	var assignedLoc *string

	query := `
		SELECT id, username, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units
		FROM users
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, userID).Scan(
		&user.UserId, &user.Username, &user.Email, &user.FullName, &user.Phone, &rolesJSON, &qualJSON, &certJSON,
