func (s *UserService) SetWorkerAvailability(ctx context.Context, actorID, actorRole, workerID string, available bool, capacityUnits int) (*models.OperationsWorker, error) {
	query := `
		UPDATE users
		SET available = $1, capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING full_name, roles
	`
	var fullName string
	var rolesJSON []byte
	err := s.db.Pool.QueryRow(ctx, query, available, capacityUnits, workerID).Scan(&fullName, &rolesJSON)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("worker_not_found")
		}
		return nil, err
	}

	// Calculate active assignment count
	var assignCount int
	_ = s.db.Pool.QueryRow(ctx, `
		SELECT COUNT(*) FROM assignments
		WHERE worker_id = $1 AND status IN ('offered', 'accepted', 'in_transit', 'in_progress', 'at_pickup', 'picked_up', 'arrived')
	`, workerID).Scan(&assignCount)

	// Fetch latest location
	var lat, lng *float64
	var recAt *time.Time
	_ = s.db.Pool.QueryRow(ctx, `
		SELECT latitude, longitude, recorded_at
		FROM worker_locations
		WHERE worker_id = $1
		ORDER BY sequence DESC, recorded_at DESC
		LIMIT 1
	`, workerID).Scan(&lat, &lng, &recAt)

	isStale := true
	var latestCoord *models.Coordinate
	if lat != nil && lng != nil && recAt != nil {
		latestCoord = &models.Coordinate{Latitude: *lat, Longitude: *lng}
		if time.Since(*recAt) < 15*time.Minute {
			isStale = false
		}
	}

	workerStatus := "available"
	if !available {
		workerStatus = "unavailable"
	}

	worker := &models.OperationsWorker{
		WorkerId:           workerID,
		WorkerIdSnake:      workerID,
		FullName:           fullName,
		Roles:              parseStringList(rolesJSON),
		Available:          available,
		Status:             workerStatus,
		CapacityUnits:      capacityUnits,
		AssignmentCount:    assignCount,
		LatestLocation:     latestCoord,
		LatestLocationSnake: latestCoord,
		LocationRecordedAt: recAt,
		LocationStale:      isStale,
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "set_worker_availability", "worker", workerID, true, map[string]interface{}{
		"available":     available,
		"capacityUnits": capacityUnits,
	})
	_, _ = s.events.Broadcast(ctx, "worker_availability_updated", "worker", workerID, map[string]interface{}{
		"workerId":      workerID,
		"available":     available,
		"capacityUnits": capacityUnits,
	})

	return worker, nil
}

func (s *UserService) RecordWorkerLocation(
	ctx context.Context,
	actorID, actorRole string,
	assignmentID string,
	coord models.Coordinate,
	sequence int,
	recordedAt time.Time,
) error {
	// Verify assignment belongs to actor (or actor is admin/dispatcher)
	var workerID string
	var sampleID string
	err := s.db.Pool.QueryRow(ctx, `
		SELECT worker_id, sample_id FROM assignments WHERE id = $1
	`, assignmentID).Scan(&workerID, &sampleID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("assignment_not_found")
		}
		return err
	}

	if actorRole != "administrator" && actorRole != "dispatcher" && workerID != actorID {
		return errors.New("forbidden")
	}

	// Check previous sequence
	var maxSeq int
	_ = s.db.Pool.QueryRow(ctx, `
		SELECT COALESCE(MAX(sequence), 0) FROM worker_locations WHERE assignment_id = $1
	`, assignmentID).Scan(&maxSeq)

	if sequence <= maxSeq {
		return errors.New("sequence_conflict")
	}

	locID := uuid.New().String()
	_, err = s.db.Pool.Exec(ctx, `
		INSERT INTO worker_locations (id, assignment_id, worker_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7)
	`, locID, assignmentID, workerID, coord.Latitude, coord.Longitude, sequence, recordedAt)
	if err != nil {
		return err
	}

	// Update sample latest location
	_, _ = s.db.Pool.Exec(ctx, `
		UPDATE samples
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, updated_at = NOW()
		WHERE id = $4
	`, coord.Latitude, coord.Longitude, recordedAt, sampleID)

	_, _ = s.events.Broadcast(ctx, "worker_location_recorded", "worker", workerID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     workerID,
		"latitude":     coord.Latitude,
		"longitude":    coord.Longitude,
		"sequence":     sequence,
		"recordedAt":   recordedAt,
	})

	return nil
}

func parseStringList(data []byte) []string {
	if len(data) == 0 {
		return []string{}
	}
	var arr []string
	_ = json.Unmarshal(data, &arr)
	return arr
}

func parseCertificationList(data []byte) []models.Certification {
	if len(data) == 0 {
		return []models.Certification{}
	}
	var arr []models.Certification
	_ = json.Unmarshal(data, &arr)
	return arr
}

func stringsContains(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr || (len(s) > 0 && len(substr) > 0 && findSubstr(s, substr)))
}

func findSubstr(s, substr string) bool {
	return len(s) >= len(substr) && (s[:len(substr)] == substr || (len(s) > 1 && findSubstr(s[1:], substr)))
}
