func (s *JourneyService) GetJourneyPlan(ctx context.Context, actorID, actorRole, journeyID string) (interface{}, error) {
	var jp models.JourneyPlan
	jp.JourneyId = journeyID

	var parentID *string
	var sampleIDsJSON []byte
	var estDelivery *time.Time

	query := `
		SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, replan_status, sample_ids
		FROM journeys
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, journeyID).Scan(
		&parentID, &jp.PlanVersion, &jp.RouteMode, &jp.Status, &estDelivery, &jp.TotalCostUnits, &jp.CapacityUsed, &jp.CapacityAvailable, &jp.ReplanStatus, &sampleIDsJSON,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("journey_not_found")
		}
		return nil, err
	}

	if parentID != nil {
		jp.ParentJourneyId = *parentID
	}
	jp.EstimatedDeliveryAt = estDelivery
	jp.SampleIds = parseStringList(sampleIDsJSON)

	// Fetch stops
	jp.OrderedStops = make([]models.JourneyStop, 0)
	stopRows, err := s.db.Pool.Query(ctx, `
		SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at, latitude, longitude
		FROM journey_stops
		WHERE journey_id = $1
		ORDER BY sequence ASC
	`, journeyID)
	if err == nil {
		for stopRows.Next() {
			var st models.JourneyStop
			var compAt *time.Time
			var lat, lng float64
			if err := stopRows.Scan(&st.StopId, &st.LocationId, &st.StopType, &st.Sequence, &st.EstimatedAt, &st.DwellMinutes, &compAt, &lat, &lng); err == nil {
				st.LocationIdSnake = st.LocationId
				st.StopTypeSnake = st.StopType
				est := st.EstimatedAt
				st.EstimatedAtSnake = &est
				st.CompletedAt = compAt
				st.Coordinate = &models.Coordinate{Latitude: lat, Longitude: lng}
				jp.OrderedStops = append(jp.OrderedStops, st)
			}
		}
		stopRows.Close()
	}

	// Fetch legs/assignments
	jp.Legs = make([]models.JourneyLeg, 0)
	jp.AssignedWorkerIds = make([]string, 0)
	jp.CollectionAssignmentIds = make([]string, 0)
	jp.NodeAssignmentIds = make([]string, 0)
	jp.LaboratoryAssignmentIds = make([]string, 0)

	assignRows, err := s.db.Pool.Query(ctx, `
		SELECT id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id
		FROM assignments
		WHERE journey_id = $1
		ORDER BY sequence ASC
	`, journeyID)
	if err == nil {
		for assignRows.Next() {
			var aid, kind, status string
			var seq int
			var fromLoc, toLoc, wID, sID *string
			if err := assignRows.Scan(&aid, &kind, &seq, &status, &fromLoc, &toLoc, &wID, &sID); err == nil {
				leg := models.JourneyLeg{
					AssignmentId:      aid,
					AssignmentIdSnake: aid,
					Sequence:          seq,
					Status:            status,
				}
				if fromLoc != nil {
					leg.FromLocationId = *fromLoc
					leg.FromLocationIdSnake = *fromLoc
				}
				if toLoc != nil {
					leg.ToLocationId = *toLoc
					leg.ToLocationIdSnake = *toLoc
				}
				if wID != nil {
					leg.WorkerId = *wID
					leg.WorkerIdSnake = *wID
					jp.AssignedWorkerIds = append(jp.AssignedWorkerIds, *wID)
				}
				if sID != nil {
					leg.SampleId = *sID
				}
				jp.Legs = append(jp.Legs, leg)

				switch kind {
				case "collection":
					jp.CollectionAssignmentId = aid
					jp.CollectionAssignmentIds = append(jp.CollectionAssignmentIds, aid)
				case "node":
					jp.NodeAssignmentIds = append(jp.NodeAssignmentIds, aid)
				case "laboratory":
					jp.LaboratoryAssignmentIds = append(jp.LaboratoryAssignmentIds, aid)
				case "transport":
					if jp.FirstTransportAssignmentId == "" {
						jp.FirstTransportAssignmentId = aid
					} else {
						jp.FinalTransportAssignmentId = aid
					}
				}
			}
		}
		assignRows.Close()
	}

	// Tailor response based on actorRole
	if actorRole == "requester" {
		var reqLegs []map[string]interface{}
		for _, leg := range jp.Legs {
			reqLegs = append(reqLegs, map[string]interface{}{
				"sequence": leg.Sequence,
				"status":   leg.Status,
			})
		}
		return &models.RequesterJourneyPlan{
			JourneyId:           jp.JourneyId,
			ParentJourneyId:     jp.ParentJourneyId,
			PlanVersion:         jp.PlanVersion,
			RouteMode:           jp.RouteMode,
			Status:              jp.Status,
			EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
			TotalCostUnits:      jp.TotalCostUnits,
			SampleIds:           jp.SampleIds,
			OrderedStops:        jp.OrderedStops,
			Legs:                reqLegs,
		}, nil
	}

	if actorRole == "collection_professional" || actorRole == "delivery_partner" || actorRole == "node_handler" || actorRole == "laboratory_team" {
		var assignedLegs []models.JourneyLeg
		var assignIDs []string
		for _, leg := range jp.Legs {
			if leg.WorkerId == actorID || actorRole == "administrator" || actorRole == "dispatcher" {
				assignedLegs = append(assignedLegs, leg)
				assignIDs = append(assignIDs, leg.AssignmentId)
			}
		}
		return &models.WorkerJourneyPlan{
			JourneyId:               jp.JourneyId,
			ParentJourneyId:         jp.ParentJourneyId,
			PlanVersion:             jp.PlanVersion,
			RouteMode:               jp.RouteMode,
			Status:                  jp.Status,
			EstimatedDeliveryAt:     jp.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIds:           assignIDs,
			SampleIds:               jp.SampleIds,
			Legs:                    assignedLegs,
			OrderedStops:            jp.OrderedStops,
			CollectionAssignmentIds: jp.CollectionAssignmentIds,
			NodeAssignmentIds:       jp.NodeAssignmentIds,
			LaboratoryAssignmentIds: jp.LaboratoryAssignmentIds,
			AssignedWorkerIds:       jp.AssignedWorkerIds,
		}, nil
	}

	return &jp, nil
}

func (s *JourneyService) AcceptAssignment(ctx context.Context, actorID, actorRole, assignmentID string) error {
	var workerID *string
	var status string
	err := s.db.Pool.QueryRow(ctx, "SELECT worker_id, status FROM assignments WHERE id = $1", assignmentID).Scan(&workerID, &status)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("assignment_not_found")
		}
		return err
	}

	if actorRole != "administrator" && (workerID == nil || *workerID != actorID) {
		return errors.New("forbidden")
	}

	_, err = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = 'accepted', updated_at = NOW() WHERE id = $1", assignmentID)
	if err != nil {
		return err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "accept_assignment", "assignment", assignmentID, true, map[string]interface{}{
		"assignmentId": assignmentID,
	})
	_, _ = s.events.Broadcast(ctx, "assignment_accepted", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     actorID,
	})

	return nil
}

func (s *JourneyService) DeclineAssignment(ctx context.Context, actorID, actorRole, assignmentID, reason string, declinedAt time.Time) error {
	return s.fairness.HandleDecline(ctx, assignmentID, actorID, reason)
}

