	var workerID *string
	err := s.db.Pool.QueryRow(ctx, "SELECT worker_id FROM assignments WHERE id = $1", assignmentID).Scan(&workerID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("assignment_not_found")
		}
		return err
	}

	if actorRole != "administrator" && actorRole != "dispatcher" && (workerID == nil || *workerID != actorID) {
		return errors.New("forbidden")
	}

	_, err = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = $1, updated_at = NOW() WHERE id = $2", status, assignmentID)
	if err != nil {
		return err
