{"path":"/workspace/backend/internal/services/operations.go","command":"create","file_text":"package services

import (
	"context"
	"encoding/json"
	"time"

	"lab-transport/internal/db"
	"lab-transport/internal/models"
	"lab-transport/internal/routing"
)

type OperationsService struct {
	db      *db.DB
	routing *routing.ServiceabilityEngine
}

func NewOperationsService(database *db.DB, rEngine *routing.ServiceabilityEngine) *OperationsService {
	return &OperationsService{
		db:      database,
		routing: rEngine,
	}
}

type OperationsFilter struct {
	SampleTypeId string `json:"sampleTypeId"`
}

func (s *OperationsService) GetOperationsState(ctx context.Context, f OperationsFilter) (*models.OperationsState, error) {
	state := &models.OperationsState{
		Samples:                   make([]models.OperationsSample, 0),
		Workers:                   make([]models.OperationsWorker, 0),
		Locations:                 make([]models.OperationsLocation, 0),
		Connections:               make([]models.OperationsConnection, 0),
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  make([]map[string]interface{}, 0),
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                make([]map[string]interface{}, 0),
		AssignmentCountSpread:    0,
		IneligibleAssignmentCount: 0,
	}

	// 1. Samples
	sampleQuery := `
		SELECT s.id, s.status, s.request_id, r.origin_lat, r.origin_lng, r.delivery_deadline, s.current_holder_id, s.active_journey_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN requests r ON s.request_id = r.id
	`
	var sampleArgs []interface{}
	if f.SampleTypeId != "" {
		sampleQuery += " WHERE s.sample_type_id = $1"
		sampleArgs = append(sampleArgs, f.SampleTypeId)
	}
	sampleRows, err := s.db.Pool.Query(ctx, sampleQuery, sampleArgs...)
	if err == nil {
		for sampleRows.Next() {
			var osamp models.OperationsSample
			var origLat, origLng, lat, lng *float64
			var delDead, recAt *time.Time
			var reqID, curHold, actJour *string

			if err := sampleRows.Scan(
				&osamp.SampleId, &osamp.Status, &reqID, &origLat, &origLng, &delDead, &curHold, &actJour, &lat, &lng, &recAt,
			); err == nil {
				osamp.SampleIdSnake = osamp.SampleId
				if reqID != nil {
					osamp.RequestId = *reqID
				}
				if origLat != nil && origLng != nil {
					osamp.Origin = &models.Coordinate{Latitude: *origLat, Longitude: *origLng}
				}
				osamp.DeliveryDeadline = delDead
				if curHold != nil {
					osamp.CurrentHolderId = *curHold
				}
				if actJour != nil {
					osamp.ActiveJourneyId = *actJour
				}
				osamp.LocationStale = true
				if lat != nil && lng != nil && recAt != nil {
					osamp.LatestLocation = &models.Coordinate{Latitude: *lat, Longitude: *lng}
					osamp.LocationRecordedAt = recAt
					if time.Since(*recAt) < 15*time.Minute {
						osamp.LocationStale = false
					}
				}
				state.Samples = append(state.Samples, osamp)
			}
		}
		sampleRows.Close()
	}

	// 2. Workers
	minAssigns := 999999
	maxAssigns := 0
	workerRows, err := s.db.Pool.Query(ctx, `
		SELECT u.id, u.full_name, u.roles, u.available, u.capacity_units
		FROM users u
		WHERE u.active = true
	`)
	if err == nil {
		for workerRows.Next() {
			var ow models.OperationsWorker
			var fullName *string
			var rolesJSON []byte
			if err := workerRows.Scan(&ow.WorkerId, &fullName, &rolesJSON, &ow.Available, &ow.CapacityUnits); err == nil {
				ow.WorkerIdSnake = ow.WorkerId
				if fullName != nil {
					ow.FullName = *fullName
				}
				ow.Roles = parseStringList(rolesJSON)
				ow.Status = "available"
				if !ow.Available {
					ow.Status = "unavailable"
				}

				// Count active assignments
				var assignCount int
				_ = s.db.Pool.QueryRow(ctx, `
					SELECT COUNT(*) FROM assignments
					WHERE worker_id = $1 AND status IN ('offered', 'accepted', 'in_transit', 'in_progress', 'at_pickup', 'picked_up', 'arrived')
				`, ow.WorkerId).Scan(&assignCount)
				ow.AssignmentCount = assignCount

				if assignCount < minAssigns {
					minAssigns = assignCount
				}
				if assignCount > maxAssigns {
					maxAssigns = assignCount
				}

				// Latest worker location
				var lat, lng *float64
				var recAt *time.Time
				_ = s.db.Pool.QueryRow(ctx, `
					SELECT latitude, longitude, recorded_at
					FROM worker_locations
					WHERE worker_id = $1
					ORDER BY sequence DESC, recorded_at DESC
					LIMIT 1
				`, ow.WorkerId).Scan(&lat, &lng, &recAt)

				ow.LocationStale = true
				if lat != nil && lng != nil && recAt != nil {
					coord := &models.Coordinate{Latitude: *lat, Longitude: *lng}
					ow.LatestLocation = coord
					ow.LatestLocationSnake = coord
					ow.LocationRecordedAt = recAt
					if time.Since(*recAt) < 15*time.Minute {
						ow.LocationStale = false
					}
				}

				state.Workers = append(state.Workers, ow)
			}
		}
		workerRows.Close()
	}

	if len(state.Workers) > 0 && minAssigns <= maxAssigns {
		state.AssignmentCountSpread = maxAssigns - minAssigns
	}

	// 3. Locations & Connections from current snapshot or DB
	snap := s.routing.GetCurrentSnapshot()
	if snap != nil {
		state.Locations = snap.ActiveLocations
		state.Connections = snap.ActiveConnections
	}

	// 4. Handoffs
	handoffRows, err := s.db.Pool.Query(ctx, `
		SELECT id, sample_id, sender_id, receiver_id, sender_confirmed, receiver_confirmed, status, created_at
		FROM handoffs
		ORDER BY created_at DESC
		LIMIT 100
	`)
	if err == nil {
		for handoffRows.Next() {
			var hid, sid, sendID, recID, stat string
			var sConf, rConf bool
			var cat time.Time
			if err := handoffRows.Scan(&hid, &sid, &sendID, &recID, &sConf, &rConf, &stat, &cat); err == nil {
				state.Handoffs = append(state.Handoffs, map[string]interface{}{
					"id":                hid,
					"sampleId":          sid,
					"senderId":          sendID,
					"receiverId":        recID,
					"senderConfirmed":   sConf,
					"receiverConfirmed": rConf,
					"status":            stat,
					"createdAt":         cat,
				})
			}
		}
		handoffRows.Close()
	}

	// 5. Exceptions
	excRows, err := s.db.Pool.Query(ctx, `
		SELECT id, status, exception_details
		FROM samples
		WHERE status = 'exception' OR exception_details IS NOT NULL
	`)
	if err == nil {
		for excRows.Next() {
			var sid, stat string
			var excJSON []byte
			if err := excRows.Scan(&sid, &stat, &excJSON); err == nil {
				var excDet map[string]interface{}
				_ = json.Unmarshal(excJSON, &excDet)
				state.Exceptions = append(state.Exceptions, map[string]interface{}{
					"sampleId": sid,
					"status":   stat,
					"details":  excDet,
				})
			}
		}
		excRows.Close()
	}

	// Count ineligible/unassigned assignments
	_ = s.db.Pool.QueryRow(ctx, `
		SELECT COUNT(*) FROM assignments
		WHERE worker_id IS NULL OR status = 'declined'
	`).Scan(&state.IneligibleAssignmentCount)

	return state, nil
}
