	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()

	var conns []models.OperationsConnection
	for rows.Next() {
		var conn models.OperationsConnection
		conn.Capacity = &models.Capacity{}
		if err := rows.Scan(
			&conn.ID, &conn.FromLocationId, &conn.ToLocationId, &conn.TravelMinutes, &conn.CostUnits, &conn.Cooled, &conn.Active,
