// Check Serviceability (Dry Run)
func (h *APIHandler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeId         string            `json:"originNodeId"`
		SampleTypeId         string            `json:"sampleTypeId"`
		RequestedAt          time.Time         `json:"requestedAt"`
		DeliveryDeadline     time.Time         `json:"deliveryDeadline"`
		EarliestCollectionAt *time.Time        `json:"earliestCollectionAt"`
		LatestCollectionAt   *time.Time        `json:"latestCollectionAt"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	st, err := h.sampleSvc.GetSampleType(r.Context(), req.SampleTypeId)
	if err != nil {
		respondError(w, http.StatusBadRequest, "sample_type_not_found", "Sample type not found")
		return
	}

	res, err := h.rEngine.EvaluateServiceability(
		r.Context(), req.Origin, req.OriginType, req.OriginNodeId, *st, req.RequestedAt, req.DeliveryDeadline, req.EarliestCollectionAt, req.LatestCollectionAt,
	)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	respondJSON(w, http.StatusOK, map[string]interface{}{
		"serviceable":         res.Serviceable,
		"reason":              res.Reason,
		"estimatedDeliveryAt": res.EstimatedDelivery,
		"collectionNodeId":    res.CollectionNodeID,
		"targetLaboratoryId":  res.TargetLaboratoryID,
	})
}

// Create Collection Request
func (h *APIHandler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var in struct {
		services.CreateCollectionRequestInput
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &in); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if in.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "create_collection_request", in.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	sampleState, err := h.sampleSvc.CreateCollectionRequest(r.Context(), u.ID, u.ActiveRole, in.CreateCollectionRequestInput)
	if err != nil {
		respondError(w, http.StatusUnprocessableEntity, "unserviceable_request", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "create_collection_request", in.IdempotencyKey, bodyBytes, http.StatusCreated, sampleState)
	respondJSON(w, http.StatusCreated, sampleState)
}

