{"file_text":"import React, { useState } from 'react';
import { api, setSessionToken } from '../api';

interface LoginProps {
  onLoginSuccess: (token: string, user: any, activeRole: string) => void;
}

export const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const res = await api.login(username, password);
      setSessionToken(res.sessionToken);
      onLoginSuccess(res.sessionToken, { id: res.userId, roles: res.roles, activeRole: res.activeRole }, res.activeRole);
    } catch (err: any) {
      setError(err.message || 'Invalid username or password. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-card">
        <h1 className="login-title" tabIndex={0}>Lab Sample Transport</h1>
        <p className="login-subtitle">Sign in to your account to manage samples & transport</p>

        {error && (
          <div className="alert alert-danger" role="alert" aria-live="polite">
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} aria-label="Sign In Form">
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              id="username"
              name="username"
              type="text"
              className="form-input"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
              autoFocus
              placeholder="Enter username"
              aria-required="true"
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              name="password"
              type="password"
              className="form-input"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              placeholder="Enter password"
              aria-required="true"
            />
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            style={{ width: '100%', marginTop: '1rem' }}
            disabled={loading}
            aria-label="Sign In"
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
      </div>
    </div>
  );
};
