{"file_text":"import React, { useEffect, useState } from 'react';
import { Sample } from '../types';
import { api } from '../api';
import { StatusTimeline } from './StatusTimeline';

interface SampleDetailModalProps {
  sampleId: string;
  onClose: () => void;
}

export const SampleDetailModal: React.FC<SampleDetailModalProps> = ({ sampleId, onClose }) => {
  const [sample, setSample] = useState<Sample | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSample = async () => {
      try {
        const res = await api.readSampleState(sampleId);
        setSample(res);
      } catch (err: any) {
        setError(err.message || 'Failed to load sample details');
      } finally {
        setLoading(false);
      }
    };
    fetchSample();
  }, [sampleId]);

  if (loading) {
    return (
      <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Sample Details Modal">
        <div className="modal-content">
          <p>Loading sample details...</p>
        </div>
      </div>
    );
  }

  if (error || !sample) {
    return (
      <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Sample Details Modal">
        <div className="modal-content">
          <div className="alert alert-danger">{error || 'Sample not found'}</div>
          <button className="btn btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>
    );
  }

  return (
    <div className="modal-overlay" role="dialog" aria-modal="true" aria-label={`Sample Details: ${sample.trackingNumber}`}>
      <div className="modal-content">
        <div className="card-header">
          <div>
            <h2 className="card-title">Sample #{sample.trackingNumber}</h2>
            <span className={`badge badge-${sample.status}`}>{sample.status}</span>
          </div>
          <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close modal">✕</button>
        </div>

        {sample.isException && (
          <div className="alert alert-danger" role="alert" aria-label="Sample Exception">
