          </div>
        )}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
          <div>
            <strong>Sample Type:</strong>
            <p>{sample.sampleTypeCode} {sample.sampleTypeName ? `(${sample.sampleTypeName})` : ''}</p>
          </div>
          <div>
            <strong>Current Custodian / Holder:</strong>
            <p>{sample.currentHolderName || sample.currentHolderId || 'Unassigned'} {sample.currentHolderRole ? `(${sample.currentHolderRole})` : ''}</p>
          </div>
          <div>
            <strong>Current Location:</strong>
            <p>
              {sample.currentLatitude && sample.currentLongitude ? (
                <>
                  {sample.currentLatitude.toFixed(4)}, {sample.currentLongitude.toFixed(4)}
