                <span className="badge badge-received">Fresh</span>
              )}
              {sample.lastLocationUpdateTime && (
                <span style={{ fontSize: '0.8rem', color: '#64748b', display: 'block' }}>
                  Updated: {new Date(sample.lastLocationUpdateTime).toLocaleString()}
                </span>
              )}
            </p>
          </div>
          <div>
            <strong>Collection Window:</strong>
            <p style={{ fontSize: '0.85rem' }}>
              {new Date(sample.collectionWindowStart).toLocaleString()} - <br />
              {new Date(sample.collectionWindowEnd).toLocaleString()}
            </p>
          </div>
          <div>
            <strong>Delivery Deadline:</strong>
            <p style={{ fontSize: '0.85rem' }}>{new Date(sample.deliveryDeadline).toLocaleString()}</p>
          </div>
          {sample.sealNumber && (
            <div>
              <strong>Seal Number:</strong>
              <p>{sample.sealNumber}</p>
            </div>
          )}
          {sample.destinationLabName && (
            <div>
              <strong>Destination Lab:</strong>
              <p>{sample.destinationLabName}</p>
            </div>
          )}
        </div>

        <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.5rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.25rem' }}>
          Status & Custody Timeline
        </h3>
        <StatusTimeline history={sample.statusHistory} />

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '1.5rem' }}>
          <button className="btn btn-secondary" onClick={onClose} aria-label="Close">Close</button>
        </div>
      </div>
    </div>
  );
};
