  const [originType, setOriginType] = useState('home');
  const [originAddress, setOriginAddress] = useState('123 MG Road, Indiranagar, Bangalore');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [sampleTypeCode, setSampleTypeCode] = useState(sampleTypes[0]?.code || 'AMBER');
  const [windowStart, setWindowStart] = useState(() => new Date(Date.now() + 15 * 60 * 1000).toISOString().slice(0, 16));
  const [windowEnd, setWindowEnd] = useState(() => new Date(Date.now() + 120 * 60 * 1000).toISOString().slice(0, 16));
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 240 * 60 * 1000).toISOString().slice(0, 16));
  const [patientNotes, setPatientNotes] = useState('');
  const [formError, setFormError] = useState<string | null>(null);
  const [formSuccess, setFormSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Serviceability Dry Run state
  const [checkLat, setCheckLat] = useState('12.9716');
  const [checkLng, setCheckLng] = useState('77.5946');
  const [checkAddress, setCheckAddress] = useState('123 MG Road, Bangalore');
  const [checkType, setCheckType] = useState(sampleTypes[0]?.code || 'AMBER');
  const [checkWindowStart, setCheckWindowStart] = useState(() => new Date(Date.now() + 15 * 60 * 1000).toISOString().slice(0, 16));
  const [checkWindowEnd, setCheckWindowEnd] = useState(() => new Date(Date.now() + 120 * 60 * 1000).toISOString().slice(0, 16));
  const [checkDeadline, setCheckDeadline] = useState(() => new Date(Date.now() + 240 * 60 * 1000).toISOString().slice(0, 16));
  const [checkResult, setCheckResult] = useState<ServiceabilityResult | null>(null);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);

  const fetchMySamples = async () => {
    setLoading(true);
    try {
