              <h2 className="card-title">In-Progress Transport Legs ({work.inProgress.length})</h2>
            </div>
            {work.inProgress.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No transport legs in progress.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="In Progress Legs Table">
