                              className="btn btn-primary btn-sm"
                              onClick={() => {
                                setProgressLeg(item);
                                setNewStatus('en_route_to_pickup');
                              }}
                              aria-label="Update progress"
                            >
                              Update Progress
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setHandoffLeg(item)}
                              aria-label="Handoff"
                            >
                              Handoff
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setCheckpointSampleId(item.sampleId || item.sample?.id)}
                              aria-label="Checkpoint"
                            >
                              Checkpoint
                            </button>
                            {item.sampleId && (
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => setSelectedSampleId(item.sampleId)}
                                aria-label="View sample"
                              >
                                View
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'past' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Completed Deliveries ({work.completed.length})</h2>
            <button className="btn btn-secondary btn-sm" onClick={fetchWork}>Refresh</button>
          </div>
          {work.completed.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No completed deliveries.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Past Deliveries Table">
                <thead>
                  <tr>
                    <th>Leg #</th>
                    <th>From</th>
                    <th>To</th>
                    <th>Completed At</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {work.completed.map((item) => (
                    <tr key={item.id}>
                      <td>Leg {item.legNumber}</td>
                      <td>{item.fromLocationName || item.fromAddress}</td>
                      <td>{item.toLocationName || item.toAddress}</td>
                      <td>{item.completedAt ? new Date(item.completedAt).toLocaleString() : 'Done'}</td>
                      <td><span className="badge badge-completed">{item.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activeTab === 'location' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Record Courier Location</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Broadcast your current GPS location to update transit tracking.
          </p>
          {locSuccess && <div className="alert alert-success">{locSuccess}</div>}

          <form onSubmit={handleRecordLocation} aria-label="Record Location Form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="courierLat">Latitude</label>
                <input
                  id="courierLat"
                  type="text"
                  className="form-input"
                  value={lat}
                  onChange={(e) => setLat(e.target.value)}
                  required
                  aria-label="Latitude"
                />
              </div>

              <div className="form-group">
                <label htmlFor="courierLng">Longitude</label>
                <input
                  id="courierLng"
                  type="text"
                  className="form-input"
                  value={lng}
                  onChange={(e) => setLng(e.target.value)}
                  required
                  aria-label="Longitude"
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Record Location">
              Record Location
            </button>
          </form>
        </div>
      )}

      {/* Progress Update Modal */}
      {progressLeg && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Update Leg Progress Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Update Leg Progress</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setProgressLeg(null)}>✕</button>
            </div>
            <form onSubmit={handleProgressSubmit} aria-label="Update Progress Form">
              <div className="form-group">
                <label htmlFor="progressStatus">New Progress Status</label>
                <select
                  id="progressStatus"
                  className="form-select"
                  value={newStatus}
                  onChange={(e) => setNewStatus(e.target.value)}
                  aria-label="Progress Status"
                >
                  <option value="en_route_to_pickup">En Route to Pickup</option>
                  <option value="arrived_at_pickup">Arrived at Pickup</option>
                  <option value="picked_up">Picked Up</option>
                  <option value="en_route_to_dropoff">En Route to Dropoff</option>
                  <option value="arrived_at_dropoff">Arrived at Dropoff</option>
                  <option value="completed_leg">Completed Leg</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="progressNotes">Notes / Observations</label>
                <textarea
                  id="progressNotes"
                  className="form-textarea"
                  rows={2}
                  value={progressNotes}
                  onChange={(e) => setProgressNotes(e.target.value)}
                  placeholder="Optional notes..."
                  aria-label="Progress Notes"
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-primary" aria-label="Update Progress">
                  Update Progress
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setProgressLeg(null)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Handoff Modal */}
      {handoffLeg && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Initiate Handoff Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Initiate Handoff</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setHandoffLeg(null)}>✕</button>
            </div>
            <form onSubmit={handleHandoffSubmit} aria-label="Handoff Form">
              <div className="form-group">
                <label htmlFor="c_handoffType">Handoff Type</label>
                <select
                  id="c_handoffType"
                  className="form-select"
                  value={handoffType}
                  onChange={(e) => setHandoffType(e.target.value)}
                  aria-label="Handoff Type"
                >
                  <option value="worker_to_node">Courier to Collection Centre / Hub</option>
                  <option value="worker_to_worker">Courier to Relay Courier</option>
                  <option value="worker_to_lab">Courier to Laboratory</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="c_targetId">Target Facility or Worker ID</label>
                <input
                  id="c_targetId"
                  type="text"
                  className="form-input"
                  value={targetId}
                  onChange={(e) => setTargetId(e.target.value)}
                  placeholder="Enter target ID"
                  aria-label="Target ID"
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-primary" aria-label="Initiate Handoff">
                  Initiate Handoff
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setHandoffLeg(null)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Checkpoint Modal */}
      {checkpointSampleId && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Record Handling Checkpoint Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Record Handling Checkpoint</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setCheckpointSampleId(null)}>✕</button>
            </div>
            <form onSubmit={handleCheckpointSubmit} aria-label="Checkpoint Form">
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="chkContainer2">Observed Container</label>
                  <select
                    id="chkContainer2"
                    className="form-select"
                    value={checkpointContainer}
                    onChange={(e) => setCheckpointContainer(e.target.value)}
                    aria-label="Observed Container"
                  >
                    <option value="standard_tube">Standard Tube</option>
                    <option value="amber_tube">Amber Tube</option>
                    <option value="cryovial">Cryovial</option>
                    <option value="insulated_box">Insulated Box</option>
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="chkTemp2">Observed Temperature (°C)</label>
                  <input
                    id="chkTemp2"
                    type="number"
                    step="0.1"
                    className="form-input"
                    value={checkpointTemp}
                    onChange={(e) => setCheckpointTemp(e.target.value)}
