                    aria-label="Observed Temperature"
                  />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-primary" aria-label="Record Checkpoint">
                  Record Checkpoint
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setCheckpointSampleId(null)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {selectedSampleId && (
        <SampleDetailModal sampleId={selectedSampleId} onClose={() => setSelectedSampleId(null)} />
      )}
    </div>
  );
};
