{"path":"/workspace/frontend/src/components/NodeHandlerView.tsx","file_text":"import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { Location, SampleType, CapacityPool } from '../types';
import { SampleDetailModal } from './SampleDetailModal';

interface NodeHandlerProps {
  user: any;
  locations: Location[];
  sampleTypes: SampleType[];
}

export const NodeHandlerView: React.FC<NodeHandlerProps> = ({ user, locations, sampleTypes }) => {
  const [activeTab, setActiveTab] = useState<'work' | 'presealed' | 'capacity' | 'handoffs'>('work');
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: [],
  });
  const [capacity, setCapacity] = useState<CapacityPool[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Presealed Sample Form State
  const [originLocationId, setOriginLocationId] = useState(locations[0]?.id || '');
  const [sampleTypeCode, setSampleTypeCode] = useState(sampleTypes[0]?.code || 'AMBER');
  const [sealNumber, setSealNumber] = useState('');
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 240 * 60 * 1000).toISOString().slice(0, 16));
  const [observedContainer, setObservedContainer] = useState('standard_tube');
  const [observedTemp, setObservedTemp] = useState('4.0');
  const [notes, setNotes] = useState('');

  // Capacity Edit State
  const [editingCapacityType, setEditingCapacityType] = useState<'regular' | 'cooled'>('regular');
  const [newUnits, setNewUnits] = useState('20');

  // Handoff confirmation state
  const [confirmSampleId, setConfirmSampleId] = useState('');
  const [confirmContainer, setConfirmContainer] = useState('standard_tube');
  const [confirmTemp, setConfirmTemp] = useState('4.0');

  const facilityId = user?.assignedFacilityId || locations[0]?.id;

  const fetchWorkAndCapacity = async () => {
    setLoading(true);
    try {
      const [workRes, capRes] = await Promise.all([
        api.listWork(),
        facilityId ? api.readCapacity(facilityId) : Promise.resolve({ data: [] }),
      ]);
      setWork({
        pending: workRes.pending || [],
        inProgress: workRes.inProgress || [],
        completed: workRes.completed || [],
      });
      setCapacity(capRes.data || (Array.isArray(capRes) ? capRes : []));
    } catch (err: any) {
      console.error('Failed to load node handler state', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWorkAndCapacity();
  }, [facilityId]);

  const handleAccept = async (legId: string) => {
    setActionError(null);
    try {
      await api.acceptAssignment(legId);
      setActionSuccess('Node assignment accepted!');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to accept assignment');
    }
  };

  const handleDecline = async (legId: string) => {
    setActionError(null);
    try {
      await api.declineAssignment(legId, 'Node handler declined');
      setActionSuccess('Assignment declined');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to decline assignment');
    }
  };

  const handlePresealedSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      const res = await api.registerPresealedSample({
        originLocationId: originLocationId || facilityId,
        sampleTypeCode,
        sealNumber,
        deliveryDeadline: new Date(deadline).toISOString(),
        observedContainer,
        observedTemperature: parseFloat(observedTemp),
        notes,
      });
      setActionSuccess(`Pre-sealed sample registered successfully! Tracking Number: ${res.sample?.trackingNumber || res.sampleId}`);
      setSealNumber('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to register pre-sealed sample');
    }
  };

  const handleCapacityUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.configureCapacity({
        facilityId,
        capacityType: editingCapacityType,
        configuredUnits: parseInt(newUnits, 10),
      });
      setActionSuccess(`${editingCapacityType.toUpperCase()} capacity updated to ${newUnits} units`);
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to update capacity');
    }
  };

  const handleConfirmHandoff = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.confirmHandoff({
        sampleId: confirmSampleId,
        observedContainer: confirmContainer,
        observedTemperature: parseFloat(confirmTemp),
      });
      setActionSuccess('Handoff confirmed and custody transferred!');
      setConfirmSampleId('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to confirm handoff');
    }
  };

  const assignedNode = locations.find((l) => l.id === facilityId);

  return (
    <div role="region" aria-label="Node Handler Portal">
      <div style={{ marginBottom: '1rem', padding: '0.75rem 1rem', background: '#e0f2fe', borderRadius: '8px', color: '#0369a1' }}>
        <strong>Assigned Node:</strong> {assignedNode ? `${assignedNode.name} (${assignedNode.code})` : 'All Node Facilities'}
      </div>

      <div className="tabs-nav" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'work' ? 'active' : ''}`}
          onClick={() => setActiveTab('work')}
          role="tab"
          aria-selected={activeTab === 'work'}
          aria-label="Node Work Tab"
        >
          Node Assignments ({work.pending.length + work.inProgress.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'presealed' ? 'active' : ''}`}
          onClick={() => setActiveTab('presealed')}
          role="tab"
          aria-selected={activeTab === 'presealed'}
          aria-label="Register Presealed Sample Tab"
        >
          + Register Pre-Sealed Sample
        </button>
        <button
          className={`tab-btn ${activeTab === 'capacity' ? 'active' : ''}`}
          onClick={() => setActiveTab('capacity')}
          role="tab"
          aria-selected={activeTab === 'capacity'}
          aria-label="Node Capacity Tab"
        >
          📦 Node Capacity
        </button>
        <button
          className={`tab-btn ${activeTab === 'handoffs' ? 'active' : ''}`}
          onClick={() => setActiveTab('handoffs')}
          role="tab"
          aria-selected={activeTab === 'handoffs'}
          aria-label="Confirm Handoff Tab"
        >
          🤝 Confirm Handoff
        </button>
      </div>

      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
        </div>
      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      {activeTab === 'work' && (
        <div>
          {/* Pending Node Offers */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Pending Node Assignments ({work.pending.length})</h2>
              <button className="btn btn-secondary btn-sm" onClick={fetchWorkAndCapacity}>Refresh</button>
            </div>
            {work.pending.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No pending node assignments.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Offered Node Assignments Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Location</th>
                      <th>Sample / Type</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.pending.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber || 1}</td>
                        <td>{item.toLocationName || item.fromLocationName || 'Node'}</td>
                        <td>{item.sampleTypeCode || 'Sample'}</td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleAccept(item.id)}
                              aria-label={`Accept node assignment ${item.id}`}
                            >
                              Accept Assignment
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDecline(item.id)}
                              aria-label={`Decline node assignment ${item.id}`}
                            >
                              Decline
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* In Progress Node Handling */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Active Node Work ({work.inProgress.length})</h2>
            </div>
            {work.inProgress.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No active node handling work.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Active Node Work Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Node</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.inProgress.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber}</td>
                        <td>{item.toLocationName || item.fromLocationName}</td>
                        <td><span className="badge badge-in_progress">{item.status}</span></td>
                        <td>
                          {item.sampleId && (
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setSelectedSampleId(item.sampleId)}
                              aria-label="View sample"
                            >
                              View Sample
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'presealed' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Register Pre-Sealed Sample</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Register a sample that was already collected and sealed before entering the system. Origin must be a clinic or network node.
          </p>

          <form onSubmit={handlePresealedSubmit} aria-label="Register Presealed Sample Form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="p_origin">Origin Facility (Clinic or Node)</label>
                <select
                  id="p_origin"
                  className="form-select"
                  value={originLocationId}
                  onChange={(e) => setOriginLocationId(e.target.value)}
                  aria-label="Origin Facility"
                >
                  {locations.map((l) => (
                    <option key={l.id} value={l.id}>
                      {l.name} ({l.code}) - {l.type}
                    </option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="p_sampleType">Sample Type</label>
                <select
                  id="p_sampleType"
                  className="form-select"
                  value={sampleTypeCode}
                  onChange={(e) => setSampleTypeCode(e.target.value)}
                  aria-label="Sample Type"
                >
                  {sampleTypes.map((st) => (
                    <option key={st.id || st.code} value={st.code}>
                      {st.name} ({st.code})
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="p_sealNumber">Seal Number / Barcode</label>
                <input
                  id="p_sealNumber"
                  type="text"
                  className="form-input"
                  value={sealNumber}
                  onChange={(e) => setSealNumber(e.target.value)}
                  required
                  placeholder="e.g. SEAL-88129"
                  aria-label="Seal Number"
                />
              </div>

              <div className="form-group">
                <label htmlFor="p_deadline">Delivery Deadline</label>
                <input
                  id="p_deadline"
                  type="datetime-local"
                  className="form-input"
                  value={deadline}
                  onChange={(e) => setDeadline(e.target.value)}
                  required
                  aria-label="Delivery Deadline"
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="p_container">Observed Container</label>
                <select
                  id="p_container"
                  className="form-select"
                  value={observedContainer}
                  onChange={(e) => setObservedContainer(e.target.value)}
                  aria-label="Observed Container"
                >
                  <option value="standard_tube">Standard Tube</option>
                  <option value="amber_tube">Amber Tube</option>
                  <option value="cryovial">Cryovial</option>
                  <option value="insulated_box">Insulated Box</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="p_temp">Observed Temperature (°C)</label>
                <input
                  id="p_temp"
                  type="number"
                  step="0.1"
                  className="form-input"
                  value={observedTemp}
                  onChange={(e) => setObservedTemp(e.target.value)}
                  required
                  aria-label="Observed Temperature"
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Register Presealed Sample">
              Register Pre-Sealed Sample
            </button>
          </form>
        </div>
      )}

      {activeTab === 'capacity' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Node Capacity ({assignedNode?.name || 'Node'})</h2>
            <button className="btn btn-secondary btn-sm" onClick={fetchWorkAndCapacity}>Refresh</button>
          </div>

