{"path":"/workspace/frontend/src/components/LabOperatorView.tsx","command":"create","file_text":"import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { Location, CapacityPool } from '../types';
import { SampleDetailModal } from './SampleDetailModal';

interface LabOperatorProps {
  user: any;
  locations: Location[];
}

export const LabOperatorView: React.FC<LabOperatorProps> = ({ user, locations }) => {
  const [activeTab, setActiveTab] = useState<'work' | 'intake' | 'capacity' | 'exception'>('work');
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: [],
  });
  const [capacity, setCapacity] = useState<CapacityPool[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Intake Form State
  const [intakeSampleId, setIntakeSampleId] = useState('');
  const [container, setContainer] = useState('standard_tube');
  const [temp, setTemp] = useState('4.0');
  const [isAccepted, setIsAccepted] = useState(true);
  const [intakeReason, setIntakeReason] = useState('');
  const [notes, setNotes] = useState('');

  // Exception Form State
  const [exceptionSampleId, setExceptionSampleId] = useState('');
  const [exceptionReason, setExceptionReason] = useState('Temperature excursion / Damaged container');
  const [exceptionDetails, setExceptionDetails] = useState('');

  // Capacity Edit State
  const [editingCapacityType, setEditingCapacityType] = useState<'regular' | 'cooled'>('regular');
  const [newUnits, setNewUnits] = useState('30');

  const facilityId = user?.assignedFacilityId || locations.find((l) => l.type === 'laboratory' || l.type === 'hub_laboratory')?.id || locations[0]?.id;

  const fetchWorkAndCapacity = async () => {
    setLoading(true);
    try {
      const [workRes, capRes] = await Promise.all([
        api.listWork(),
        facilityId ? api.readCapacity(facilityId) : Promise.resolve({ data: [] }),
      ]);
      setWork({
        pending: workRes.pending || [],
        inProgress: workRes.inProgress || [],
        completed: workRes.completed || [],
      });
      setCapacity(capRes.data || (Array.isArray(capRes) ? capRes : []));
    } catch (err: any) {
      console.error('Failed to load lab operator data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWorkAndCapacity();
  }, [facilityId]);

  const handleAccept = async (legId: string) => {
    setActionError(null);
    try {
      await api.acceptAssignment(legId);
      setActionSuccess('Lab assignment accepted!');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to accept assignment');
    }
  };

  const handleDecline = async (legId: string) => {
    setActionError(null);
    try {
      await api.declineAssignment(legId, 'Lab operator declined');
      setActionSuccess('Assignment declined');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to decline assignment');
    }
  };

  const handleIntakeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.confirmLabReceipt({
        sampleId: intakeSampleId,
        laboratoryId: facilityId,
        observedContainer: container,
        observedTemperature: parseFloat(temp),
        isAccepted,
        exceptionReason: !isAccepted ? intakeReason : undefined,
        notes,
      });
      setActionSuccess(isAccepted ? 'Sample received and journey completed!' : 'Sample marked with intake rejection exception');
      setIntakeSampleId('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to process lab receipt');
    }
  };

  const handleExceptionSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.recordSampleException({
        sampleId: exceptionSampleId,
        reason: exceptionReason,
        details: exceptionDetails,
      });
      setActionSuccess('Sample exception recorded successfully');
      setExceptionSampleId('');
      setExceptionDetails('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to record exception');
    }
  };

  const handleCapacityUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.configureCapacity({
        facilityId,
        capacityType: editingCapacityType,
        configuredUnits: parseInt(newUnits, 10),
      });
      setActionSuccess(`${editingCapacityType.toUpperCase()} capacity updated to ${newUnits} units`);
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to update capacity');
    }
  };

  const assignedLab = locations.find((l) => l.id === facilityId);

  return (
    <div role="region" aria-label="Laboratory Intake Portal">
      <div style={{ marginBottom: '1rem', padding: '0.75rem 1rem', background: '#f3e8ff', borderRadius: '8px', color: '#6b21a8' }}>
