          role="tab"
          aria-selected={activeTab === 'work'}
          aria-label="Expected Samples Tab"
        >
          Expected & In-Progress ({work.pending.length + work.inProgress.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'intake' ? 'active' : ''}`}
          onClick={() => setActiveTab('intake')}
          role="tab"
          aria-selected={activeTab === 'intake'}
          aria-label="Confirm Receipt Tab"
        >
          🔬 Confirm Receipt
        </button>
        <button
          className={`tab-btn ${activeTab === 'capacity' ? 'active' : ''}`}
          onClick={() => setActiveTab('capacity')}
          role="tab"
          aria-selected={activeTab === 'capacity'}
          aria-label="Lab Capacity Tab"
        >
          📦 Lab Capacity
        </button>
        <button
          className={`tab-btn ${activeTab === 'exception' ? 'active' : ''}`}
          onClick={() => setActiveTab('exception')}
          role="tab"
          aria-selected={activeTab === 'exception'}
          aria-label="Record Exception Tab"
        >
          ⚠️ Record Exception
        </button>
      </div>

      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
