      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      {activeTab === 'work' && (
        <div>
          {/* Pending Intake Offers */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Pending Lab Intake Offers ({work.pending.length})</h2>
              <button className="btn btn-secondary btn-sm" onClick={fetchWorkAndCapacity}>Refresh</button>
            </div>
            {work.pending.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No pending intake offers.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Offered Intake Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Facility</th>
                      <th>Sample Type</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.pending.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber || 1}</td>
                        <td>{item.toLocationName || 'Lab'}</td>
                        <td>{item.sampleTypeCode || 'Sample'}</td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleAccept(item.id)}
                              aria-label={`Accept intake assignment ${item.id}`}
                            >
                              Accept Assignment
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDecline(item.id)}
                              aria-label={`Decline intake assignment ${item.id}`}
                            >
                              Decline
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* In Progress Intake */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Expected Incoming Samples ({work.inProgress.length})</h2>
            </div>
            {work.inProgress.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No expected samples currently.</p>
            ) : (
