                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-primary btn-sm"
                              onClick={() => {
                                setIntakeSampleId(item.sampleId || item.sample?.id);
                                setActiveTab('intake');
                              }}
                              aria-label="Process intake"
                            >
                              Process Intake
                            </button>
                            {item.sampleId && (
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => setSelectedSampleId(item.sampleId)}
