                              >
                                View
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'intake' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Confirm Laboratory Receipt</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Inspect incoming sample container and temperature before accepting into the laboratory.
          </p>

          <form onSubmit={handleIntakeSubmit} aria-label="Confirm Lab Receipt Form" style={{ maxWidth: '600px' }}>
            <div className="form-group">
              <label htmlFor="in_sampleId">Sample ID or Tracking Number</label>
              <input
                id="in_sampleId"
