{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import React, { useState, useEffect } from 'react';
import { api, setSessionToken, getSessionToken } from './api';
import { User, Location, SampleType } from './types';
import { Login } from './components/Login';
import { RequesterView } from './components/RequesterView';
import { CollectorView } from './components/CollectorView';
import { CourierView } from './components/CourierView';
import { NodeHandlerView } from './components/NodeHandlerView';
import { LabOperatorView } from './components/LabOperatorView';
import { DispatcherDashboard } from './components/DispatcherDashboard';
import { AdminView } from './components/AdminView';
import { AuditLogView } from './components/AuditLogView';

export const App: React.FC = () => {
  const [token, setToken] = useState<string | null>(getSessionToken());
  const [user, setUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<string>('');
  const [locations, setLocations] = useState<Location[]>([]);
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [viewMode, setViewMode] = useState<'main' | 'audit' | 'admin'>('main');

  const fetchBootstrapData = async () => {
    try {
      const res = await api.getBootstrap();
      if (res.user) {
        setUser(res.user);
        setActiveRole(res.activeRole || res.user.activeRole || (res.user.roles && res.user.roles[0]) || 'requester');
      }
      setLocations(res.locations || []);
      setSampleTypes(res.sampleTypes || []);
    } catch (err) {
      console.error('Failed to load bootstrap data', err);
      // If token expired or invalid, reset
      if (token) {
        handleSignOut();
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) {
      fetchBootstrapData();
    } else {
      setLoading(false);
    }
  }, [token]);

  const handleLoginSuccess = (newToken: string, loggedInUser: any, selectedRole: string) => {
    setToken(newToken);
    setUser(loggedInUser);
    setActiveRole(selectedRole || (loggedInUser.roles && loggedInUser.roles[0]) || 'requester');
    fetchBootstrapData();
  };

  const handleSignOut = () => {
    setSessionToken(null);
    setToken(null);
    setUser(null);
    setActiveRole('');
    setViewMode('main');
  };

  const handleRoleChange = async (newRole: string) => {
    try {
      await api.selectActiveRole(newRole);
      setActiveRole(newRole);
      setViewMode('main');
      if (user) {
        setUser({ ...user, activeRole: newRole });
      }
    } catch (err) {
      console.error('Failed to switch active role', err);
    }
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}>
        <p style={{ fontSize: '1.1rem', color: '#475569' }}>Loading Lab Transport System...</p>
      </div>
    );
  }

  if (!token || !user) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const userRoles = user.roles || [activeRole || 'requester'];
  const canAccessAudit = activeRole === 'dispatcher' || activeRole === 'administrator' || userRoles.includes('administrator') || userRoles.includes('dispatcher');
  const canAccessAdmin = activeRole === 'administrator' || userRoles.includes('administrator');

  return (
    <div className="app-container">
      {/* Top Navigation Bar */}
      <header className="top-nav">
        <div className="nav-brand">
          <span style={{ fontSize: '1.3rem' }}>🧪</span>
          <span>Lab Transport System</span>
        </div>

        <div className="nav-controls">
          {/* Active Role Selector */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <label htmlFor="roleSwitcher" style={{ fontSize: '0.85rem', fontWeight: 600, color: '#334155' }}>
              Role Context:
            </label>
            <select
              id="roleSwitcher"
              className="form-select"
              style={{ width: 'auto', padding: '0.35rem 0.65rem', fontSize: '0.85rem', fontWeight: 600 }}
              value={activeRole}
              onChange={(e) => handleRoleChange(e.target.value)}
              aria-label="Switch Active Role Context"
            >
              {userRoles.map((role) => (
                <option key={role} value={role}>
                  {role.replace(/_/g, ' ').toUpperCase()}
                </option>
              ))}
            </select>
          </div>

          {/* Navigation Links for Dispatcher / Admin */}
          {canAccessAudit && (
            <button
              className={`btn btn-sm ${viewMode === 'audit' ? 'btn-primary' : 'btn-secondary'}`}
              onClick={() => setViewMode(viewMode === 'audit' ? 'main' : 'audit')}
              aria-label="Toggle Audit Logs"
            >
              Audit Trail
            </button>
          )}

          {canAccessAdmin && (
            <button
              className={`btn btn-sm ${viewMode === 'admin' ? 'btn-primary' : 'btn-secondary'}`}
              onClick={() => setViewMode(viewMode === 'admin' ? 'main' : 'admin')}
              aria-label="Toggle Admin Portal"
            >
              Administration
            </button>
          )}

          {/* User Info & Sign Out */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', borderLeft: '1px solid #e2e8f0', paddingLeft: '0.75rem' }}>
            <span style={{ fontSize: '0.85rem', color: '#475569', fontWeight: 500 }}>
              {user.fullName || user.username}
            </span>
            <button
              className="btn btn-secondary btn-sm"
              onClick={handleSignOut}
              aria-label="Sign Out"
            >
              Sign Out
            </button>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="main-content">
        {viewMode === 'audit' && <AuditLogView />}

        {viewMode === 'admin' && (
          <AdminView
            locations={locations}
            sampleTypes={sampleTypes}
            onRefresh={fetchBootstrapData}
          />
        )}

        {viewMode === 'main' && (
          <>
            {activeRole === 'requester' && (
              <RequesterView sampleTypes={sampleTypes} />
            )}

            {activeRole === 'certified_collection_professional' && (
              <CollectorView />
            )}

            {activeRole === 'relay_courier' && (
              <CourierView />
            )}

            {activeRole === 'node_handler' && (
              <NodeHandlerView user={user} locations={locations} sampleTypes={sampleTypes} />
            )}

            {activeRole === 'laboratory_intake_operator' && (
              <LabOperatorView user={user} locations={locations} />
            )}

            {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
              <DispatcherDashboard />
            )}
          </>
        )}
      </main>
    </div>
  );
};
"}

